package com.martins.whisper.asr

import org.json.JSONObject

/**
 * Expected-transcript manifest committed with the golden fixtures
 * (app/src/test/resources/golden/fleurs-manifest.json, generated by
 * scripts/verify/fetch-golden-fleurs.sh). Audio itself is never in git:
 * audioName is resolved under the fixtures dir ($WHISPER_FLEURS_DIR).
 */
object FleursManifest {

    data class Clip(
        val language: String,
        val config: String,
        val split: String,
        val sourceId: String,
        val rowId: Int,
        val durationSeconds: Double,
        val cer: Boolean,
        val audioName: String,
        val expected: String,
    )

    fun parse(): List<Clip> {
        val raw = FleursManifest::class.java.getResourceAsStream("/golden/fleurs-manifest.json")
            ?: throw AssertionError("fleurs-manifest.json missing from test resources")
        val text = raw.bufferedReader().readText()
        val root = JSONObject(text)
        val arr = root.getJSONArray("clips")
        val clips = ArrayList<Clip>(arr.length())
        for (i in 0 until arr.length()) {
            val o = arr.getJSONObject(i)
            clips += Clip(
                language = o.getString("language"),
                config = o.optString("config"),
                split = o.optString("split", "validation"),
                sourceId = o.getString("sourceId"),
                rowId = o.getInt("rowId"),
                durationSeconds = o.optDouble("durationSeconds", 0.0),
                cer = o.optBoolean("cer", false),
                audioName = o.getString("audioFile").removePrefix("FLEURS_DIR/"),
                expected = o.getString("expectedTranscript"),
            )
        }
        return clips
    }
}
